<?php
declare(strict_types=1);
namespace TempNumber;
require __DIR__.'/../src/bootstrap.php';foreach(['Wallet','Pricing','Providers','Rentals','Payments','Commerce','Reconciliation','SmmOrders','TempMail','AccountMail']as$file)require __DIR__.'/../src/'.$file.'.php';
$lock=fopen(__DIR__.'/../storage/jobs.lock','c');if(!flock($lock,LOCK_EX|LOCK_NB)){echo "Already running.\n";exit(0);}$id=id();$started=time();query('INSERT INTO job_runs (id,name,status,started_at) VALUES (?,?,?,?)',[$id,'synchronise','running',now()]);$summary=['synced'=>0,'deferred'=>0,'mail_sent'=>0];
try{$summary['account_mail']=AccountMail::deliver(null,3);$summary['number_refunds']=Rentals::expireDue();foreach(all("SELECT * FROM orders WHERE product IN ('usa','global') AND status IN ('active','pending','reconciliation') ORDER BY updated_at LIMIT 100") as $o){if(time()-$started>45)break;try{if(!$o['provider_order_id'])Reconciliation::run($o['id']);else Rentals::sync($o);$summary['synced']++;}catch(\Throwable){$summary['deferred']++;}}
 foreach(all("SELECT id FROM fulfilment_intents WHERE status IN ('pending','reconciliation') ORDER BY updated_at LIMIT 20")as$i){if(time()-$started>45)break;try{Reconciliation::run($i['id']);}catch(\Throwable){$summary['deferred']++;}}
 foreach(all("SELECT * FROM orders WHERE product IN ('long-term','dedicated') AND status='active' ORDER BY updated_at LIMIT 20")as$o){if(time()-$started>45)break;try{Commerce::synchronise($o['product'],$o);$summary['synced']++;}catch(\Throwable){$summary['deferred']++;}}
 foreach(all("SELECT * FROM orders WHERE product IN ('long-term','dedicated') AND auto_renew=1 AND status='active' AND expires_at<? ORDER BY expires_at LIMIT 20",[gmdate('Y-m-d H:i:s',time()+300)])as$o){if(time()-$started>45)break;try{$customer=one('SELECT * FROM users WHERE id=?',[$o['user_id']]);if($customer['status']!=='active')continue;Commerce::fulfil($customer,$o['product'],'renewal',['id'=>$o['id']],'job-renew:'.$o['id']);}catch(\Throwable){$summary['deferred']++;}}
 foreach(all("SELECT * FROM smm_orders WHERE status IN ('pending','active','reconciliation') ORDER BY COALESCE(last_status_at,'1970-01-01 00:00:00') LIMIT 20")as$o){if(time()-$started>45)break;try{SmmOrders::refresh($o);$summary['synced']++;}catch(\Throwable){$summary['deferred']++;}}
 foreach(all("SELECT r.id,o.user_id FROM smm_refills r JOIN smm_orders o ON o.id=r.order_id WHERE r.status IN ('pending','active') AND r.provider_refill_id IS NOT NULL ORDER BY r.updated_at LIMIT 10")as$r){if(time()-$started>45)break;try{SmmOrders::refillStatus(['id'=>$r['user_id']],$r['id']);$summary['synced']++;}catch(\Throwable){$summary['deferred']++;}}
 foreach(all("SELECT id FROM payments WHERE status='pending' AND provider_reference IS NOT NULL ORDER BY updated_at LIMIT 20")as$p){if(time()-$started>45)break;try{Payments::verify($p['id']);}catch(\Throwable){$summary['deferred']++;}}
 foreach(all("SELECT id FROM temp_mail_operations WHERE status='pending' AND operation='create' AND updated_at<? ORDER BY updated_at LIMIT 10",[gmdate('Y-m-d H:i:s',time()-60)])as$pending){if(time()-$started>45)break;try{TempMail::recover($pending['id']);$summary['synced']++;}catch(\Throwable){$summary['deferred']++;}}
 // Local expiry hides an inbox; financial refunds still require authoritative provider outcomes.
 query("UPDATE inboxes SET status='expired' WHERE expires_at<? AND status='active'",[now()]);
 foreach(all("SELECT t.*,u.email FROM support_tickets t JOIN users u ON u.id=t.user_id WHERE t.status='pending_email' AND NOT EXISTS (SELECT 1 FROM transactional_mail m WHERE m.support_ticket_id=t.id) ORDER BY t.created_at LIMIT 10")as$t){if(!env('SUPPORT_EMAIL')||!env('SMTP_HOST')||time()-$started>45)break;try{sendMail(env('SUPPORT_EMAIL'),'Wallet support '.$t['id'],'Account: '.$t['email']."\nReference: ".$t['payment_reference']."\n".$t['description']."\nReceipt retained securely: ".$t['id']);query("UPDATE support_tickets SET status='submitted' WHERE id=?",[$t['id']]);$summary['mail_sent']++;}catch(\Throwable){$summary['deferred']++;}}
 query('DELETE FROM rate_limits WHERE expires_at<?',[now()]);query('DELETE FROM sessions WHERE expires_at<?',[now()]);query('DELETE FROM oauth_states WHERE expires_at<?',[now()]);query('UPDATE job_runs SET status=?,summary=?,finished_at=? WHERE id=?',['complete',json_encode($summary),now(),$id]);echo json_encode($summary).PHP_EOL;
}catch(\Throwable $e){query('UPDATE job_runs SET status=?,summary=?,finished_at=? WHERE id=?',['failed',json_encode(['error'=>get_class($e)]),now(),$id]);exit(1);}finally{flock($lock,LOCK_UN);fclose($lock);}
